static BOOL WINAPI get_attr_value_callback( ULONG attr_id, BYTE *stream, ULONG stream_size,
                                            void *params )
{
    struct get_attr_value_data *args = params;
    if (attr_id == args->attr_id)
    {
        args->attr_stream = stream;
        args->stream_size = stream_size;
        return FALSE;
    }
    return TRUE;
}

